import {ACCESSORIES,MUZZLES} from './equipment.mjs';
import {RECIPES} from './catalog.mjs';
import {weaponName} from './evolutions.mjs';
export function openInstallation({run,id,$,showDialog,closeDialog,onInstalled,icons={}}){
 if(run.state!=='reward'||!run.rewardChoices.includes(id))return;
 run.saveWeapon();const muzzle=run.rewardKind==='muzzle',catalog=muzzle?MUZZLES:ACCESSORIES,item=catalog[id];if(!item)return;
 const positions=[];run.weapons.forEach((w,wi)=>{for(const slot of muzzle?[0]:[0,1]){const old=(muzzle?w.muzzle:w.attachments[slot])||null;positions.push({wi,slot,old,active:muzzle||item.gun===w.gun?.type,duplicate:muzzle?old===id:w.attachments.includes(id)})}});
 const recommended=positions.findIndex(p=>!p.old&&p.active&&!p.duplicate),firstEmpty=positions.findIndex(p=>!p.old&&!p.duplicate);
 const where=p=>`枪槽${p.wi+1} · ${run.weapons[p.wi].gun?weaponName(run.weapons[p.wi].gun):'空武器槽'} · ${muzzle?'枪口':'配件'+(p.slot+1)}`;
 const effect=p=>p.active?'✓ 安装后生效':'暂不生效 · 需要'+RECIPES[item.gun].name;
 const stillAvailable=p=>run.state==='reward'&&run.rewardChoices.includes(id)&&((muzzle?run.weapons[p.wi].muzzle:run.weapons[p.wi].attachments[p.slot])||null)===p.old;
 const install=p=>{if(p.duplicate)return;if(!stillAvailable(p)){render();return}if(run.chooseReward(id,{weapon:p.wi,slot:p.slot})){closeDialog(false);onInstalled()}};
 function confirm(p){if(!stillAvailable(p)){render();return}const previous=catalog[p.old];showDialog('replacement-confirm',`<div class="eyebrow">REPLACE COMPONENT / 替换已有组件</div><h2>确认替换？</h2><p class="replacement-location">${where(p)}</p><div class="replacement-comparison"><div class="replacement-old"><small>当前已安装 · 将移除</small><strong>${previous?.name||'当前组件'}</strong><p>${previous?.description||''}</p></div><span class="replacement-arrow">→</span><div class="replacement-new"><small>准备安装</small><strong>${item.name}</strong><p>${item.description}</p><span class="${p.active?'fit-active':'fit-inactive'}">${effect(p)}</span></div></div><p class="replacement-warning">确认后移除当前${muzzle?'枪口':'配件'}，安装${item.name}。</p><div class="replacement-actions"><button id="keepModule" class="cancel">保留原组件，重新选位置</button><button id="confirmModuleReplacement" class="replace-confirm">确认替换</button></div>`);$('keepModule').onclick=render;$('confirmModuleReplacement').onclick=()=>install(p);$('keepModule').focus({preventScroll:true})}
 function render(){if(run.state!=='reward'||!run.rewardChoices.includes(id))return;showDialog('replacement',`<div class="eyebrow">CHOOSE AN INSTALLATION SLOT / 安装位置</div><h2>安装<span>${item.name}</span></h2><div class="installation-selected"><span>${icons[id]||'⚙'}</span><p>${item.description}</p></div><p class="installation-legend"><span>＋ 空槽 · 直接安装</span><span>⇄ 已安装 · 替换需确认</span></p>${run.weapons.map((w,wi)=>`<section class="installation-weapon"><div class="installation-weapon-title"><b>枪槽${wi+1} · ${w.gun?weaponName(w.gun):'空武器槽'}</b><small>空槽 ${positions.filter(p=>p.wi===wi&&!p.old).length}/${muzzle?1:2}</small></div><div class="installation-grid ${muzzle?'is-muzzle':''}">${positions.map((p,i)=>{if(p.wi!==wi)return '';return `<button id="installSlot${i}" class="install-option ${p.old?'install-occupied':'install-empty'} ${i===recommended?'install-recommended':''}" ${p.duplicate?'disabled':''}><div class="install-slot-top"><small>${muzzle?'枪口槽':'配件槽 '+(p.slot+1)}</small><span class="install-slot-badge">${p.old?'已安装':i===recommended?'空槽 · 推荐':'空槽'}</span></div><div class="install-slot-main"><span class="install-slot-symbol">${p.old?(icons[p.old]||'⚙'):'＋'}</span><b>${p.old?(catalog[p.old]?.name||'当前组件'):'未安装组件'}</b></div><span class="install-compatibility ${p.active?'fit-active':'fit-inactive'}">${p.duplicate?(muzzle?'此枪已装同名枪口':'此枪已装同名配件'):effect(p)}</span><span class="install-slot-action">${p.duplicate?'已安装，无需重复':p.old?'⇄ 替换此组件 · 需确认':'＋ 安装到空槽'}</span></button>`}).join('')}</div></section>`).join('')}<button id="cancelRewardSwap" class="back-link">返回战利品</button>`);
 positions.forEach((p,i)=>{$('installSlot'+i).onclick=()=>{if(p.duplicate)return;if(p.old)confirm(p);else install(p)}});$('cancelRewardSwap').onclick=()=>closeDialog();const focus=recommended>=0?recommended:firstEmpty;if(focus>=0)$('installSlot'+focus).focus({preventScroll:true});else $('cancelRewardSwap').focus({preventScroll:true})}
 render();
}
